//! Analyse a session's event log: print each entry's kind and timestamp.

use std::path::{Path, PathBuf};

fn main() {
    // Positional: working dir (default ./working) then session name
    // (default default-session). Matches the `hanihi-session` CLI.
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (working_dir, session_name) = match args.as_slice() {
        [] => (PathBuf::from("./working"), "default-session".to_string()),
        [name] => (PathBuf::from("./working"), name.clone()),
        [dir, name] => (PathBuf::from(dir), name.clone()),
        _ => {
            eprintln!("usage: analyse [WORKING_DIR] [SESSION_NAME]");
            std::process::exit(2);
        }
    };

    if let Err(e) = run(&working_dir, &session_name) {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

fn run(working_dir: &Path, name: &str) -> Result<(), String> {
    let path = events_path(working_dir, name);
    for (kind, ts) in read_entries(&path)? {
        println!("{kind}\t{ts}");
    }
    Ok(())
}

fn events_path(working_dir: &Path, name: &str) -> PathBuf {
    working_dir.join("sessions").join(name).join("events.jsonl")
}

/// Read `kind` and `ts` from every line of an `events.jsonl` file.
fn read_entries(path: &Path) -> Result<Vec<(String, String)>, String> {
    let content =
        std::fs::read_to_string(path).map_err(|e| format!("reading {}: {e}", path.display()))?;

    let mut entries = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let value: serde_json::Value = serde_json::from_str(line)
            .map_err(|e| format!("{} line {}: {e}", path.display(), i + 1))?;
        let kind = value
            .get("kind")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown")
            .to_string();
        let ts = value
            .get("ts")
            .and_then(|v| v.as_str())
            .unwrap_or("n/a")
            .to_string();
        entries.push((kind, ts));
    }
    Ok(entries)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_events() -> PathBuf {
        std::env::temp_dir().join(format!("analyse-test-{}.jsonl", uuid::Uuid::new_v4()))
    }

    #[test]
    fn reads_kind_and_ts_per_line() {
        let path = temp_events();
        std::fs::write(
            &path,
            concat!(
                "{\"kind\":\"session_created\",\"ts\":\"2026-09-01T02:56:38Z\",\"turn\":0,\"data\":{}}\n",
                "{\"kind\":\"turn_complete\",\"ts\":\"2026-09-01T03:00:00Z\",\"turn\":1,\"data\":{}}\n",
                "\n",
            ),
        )
        .expect("write");

        let entries = read_entries(&path).expect("read");

        assert_eq!(
            entries,
            vec![
                ("session_created".to_string(), "2026-09-01T02:56:38Z".to_string()),
                ("turn_complete".to_string(), "2026-09-01T03:00:00Z".to_string()),
            ]
        );

        std::fs::remove_file(&path).unwrap_or(());
    }
}

