            }
        };

        let kind = value.get("kind").and_then(serde_json::Value::as_str);
        let ts = value.get("ts").and_then(serde_json::Value::as_str);
        if let (Some(kind), Some(ts)) = (kind, ts) {
            println!("{kind}\t{ts}");
        }
    }
}

