        let mut rx = session
            .run_streaming(&mut agent, "p", "m", "echo hello")
            .await
            .expect("run streaming");
        while (rx.recv().await).is_some() {}

        let events = session.events().expect("events");
        let exec = events
            .iter()
            .find_map(|e| match e {
                LogEntry::ToolExecution { data, .. } => Some(data),
                _ => None,
