        let mut mgr = SessionManager::new(&dir);
        let session = mgr
            .create("replay-text", "deepseek-chat", "p")
            .expect("create");
        let now = Utc::now();
        write_log(
            session,
            &[
                LogEntry::user_input(now, 1, "hello".into()),
                LogEntry::llm_prompt(
                    now,
                    1,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("msg_1".into()),
                    Some("hi there".into()),
